function CinematicEffects(){
 const [soundOn,setSoundOn]=useState(()=>{try{return localStorage.getItem('dinuvox-sound')==='on'}catch{return false}});
 useEffect(()=>{
  document.documentElement.classList.add('cinematic-ready');
  const audioContext=()=>{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)return null;return new Ctx()};
  const tone=(kind='click')=>{if(!soundOn)return;try{const ctx=audioContext();if(!ctx)return;const osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);const now=ctx.currentTime;osc.type='sine';osc.frequency.setValueAtTime(kind==='hover'?620:kind==='close'?240:kind==='success'?880:420,now);osc.frequency.exponentialRampToValueAtTime(kind==='hover'?760:kind==='close'?150:kind==='success'?1100:560,now+.055);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(kind==='hover'?.018:.035,now+.008);gain.gain.exponentialRampToValueAtTime(.0001,now+.085);osc.start(now);osc.stop(now+.09);osc.onended=()=>ctx.close()}catch{}};
  const onClick=e=>{const target=e.target.closest('button,a,[role="button"],input[type="checkbox"],input[type="radio"],summary');if(!target)return;const label=(target.getAttribute('aria-label')||target.innerText||'').toLowerCase();tone(/close|cancel|back|dismiss/.test(label)?'close':/save|submit|create|publish|success|done/.test(label)?'success':'click')};
  const onHover=e=>{const target=e.target.closest('button,a,[role="button"],.form-card,.template-card,.stat-card,.panel,.nav-item,.theme-option,.field-row');if(target&&!target.contains(e.relatedTarget))tone('hover')};
  document.addEventListener('click',onClick,true);document.addEventListener('pointerover',onHover,true);
  const onPageHide=()=>document.documentElement.classList.add('cinematic-exit');window.addEventListener('pagehide',onPageHide);
  return()=>{document.removeEventListener('click',onClick,true);document.removeEventListener('pointerover',onHover,true);window.removeEventListener('pagehide',onPageHide);document.documentElement.classList.remove('cinematic-ready','cinematic-exit')};
 },[soundOn]);
 const toggle=()=>setSoundOn(v=>{const next=!v;try{localStorage.setItem('dinuvox-sound',next?'on':'off')}catch{}return next});
 return <button className="sound-toggle" type="button" aria-pressed={soundOn} onClick={toggle} title={soundOn?'Turn interface sounds off':'Turn interface sounds on'}><span className="sound-pulse"/><span>{soundOn?'SOUND ON':'SOUND OFF'}</span><span className="sound-bars" aria-hidden="true"><i/><i/><i/><i/></span></button>
}
function App(){
 const [session,setSession] = useState(null); const [authReady,setAuthReady] = useState(false); const [profile,setProfile] = useState(null);
 useEffect(()=>{ if(!supabase){setAuthReady(true);return;} supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthReady(true)}); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>{setSession(s);setAuthReady(true)}); return ()=>subscription.unsubscribe(); },[]);
 useEffect(()=>{if(session?.user){setProfile(session.user.user_metadata?.full_name || session.user.email?.split('@')[0] || 'Creator')}else setProfile(null)},[session]);
 useEffect(()=>{const applyTheme=()=>{const theme=localStorage.getItem('dinuvox-theme')||'system';const dark=theme==='dark'||(theme==='system'&&window.matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';};applyTheme();const media=window.matchMedia('(prefers-color-scheme: dark)');media.addEventListener?.('change',applyTheme);window.addEventListener('storage',applyTheme);return()=>{media.removeEventListener?.('change',applyTheme);window.removeEventListener('storage',applyTheme);};},[]);
 if(!configured) return <Setup />;
 if(!authReady) return <div className="loading-screen"><div className="spinner"/><p>Preparing your workspace…</p></div>;
 return <><CinematicEffects/><Routes><Route path="/" element={session?<Navigate to="/dashboard" replace/>:<Landing/>}/><Route path="/login" element={session?<Navigate to="/dashboard" replace/>:<AuthPage mode="login"/>}/><Route path="/register" element={session?<Navigate to="/dashboard" replace/>:<AuthPage mode="register"/>}/><Route path="/f/:slug" element={<PublicForm/>}/><Route path="/dashboard" element={<Protected session={session}><Shell profile={profile} onLogout={()=>supabase.auth.signOut()}><Dashboard/></Shell></Protected>}/><Route path="/templates" element={<Protected session={session}><Shell profile={profile} onLogout={()=>supabase.auth.signOut()}><Templates/></Shell></Protected>}/><Route path="/studio/:id" element={<Protected session={session}><Shell profile={profile} onLogout={()=>supabase.auth.signOut()}><Studio/></Shell></Protected>}/><Route path="/responses/:id" element={<Protected session={session}><Shell profile={profile} onLogout={()=>supabase.auth.signOut()}><Responses/></Shell></Protected>}/><Route path="/analytics" element={<Protected session={session}><Shell profile={profile} onLogout={()=>supabase.auth.signOut()}><Analytics/></Shell></Protected>}/><Route path="/settings" element={<Protected session={session}><Shell profile={profile} onLogout={()=>supabase.auth.signOut()}><SettingsPage profile={profile}/></Shell></Protected>}/><Route path="*" element={<NotFound/>}/></Routes></>
}
function Setup(){const [urlValue,setUrlValue]=useState(()=>localStorage.getItem('dinuvox-supabase-url')||'');const [keyValue,setKeyValue]=useState(()=>localStorage.getItem('dinuvox-supabase-key')||'');const [message,setMessage]=useState('');function connect(e){e.preventDefault();const u=urlValue.trim().replace(/\/$/,'');const k=keyValue.trim();if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(u)){setMessage('Enter the Supabase Project URL, such as https://your-project.supabase.co (do not add /rest/v1).');return}if(!k){setMessage('Paste your Supabase publishable/anon key.');return}localStorage.setItem('dinuvox-supabase-url',u);localStorage.setItem('dinuvox-supabase-key',k);setMessage('Saved for this browser. Reloading…');window.location.reload()}return <div className="setup-wrap"><div className="brand-mark">D<span>V</span></div><form className="setup-card setup-connector" onSubmit={connect}><span className="eyebrow">INDEPENDENT BUILD</span><h1>Connect your workspace</h1><p>DinuVoX Forms is independent from Base44. Connect your Supabase project to enable sign-in, saved forms, public submissions and analytics.</p><label className="form-label">Supabase Project URL<input type="url" value={urlValue} onChange={e=>setUrlValue(e.target.value)} placeholder="https://your-project.supabase.co" autoComplete="url" required /></label><label className="form-label">Publishable / anon key<input type="password" value={keyValue} onChange={e=>setKeyValue(e.target.value)} placeholder="Paste your browser-safe Supabase key" autoComplete="off" required /></label><button className="btn btn-primary btn-full" type="submit">Connect workspace <ArrowRight size={16}/></button>{message&&<p className="error-box" role="status">{message}</p>}<p className="muted small">Use only your publishable/anon key. Never paste a service-role or secret key here. Values are saved only in this browser.</p><div className="code-note">VITE_SUPABASE_URL<br/>VITE_SUPABASE_ANON_KEY</div><p className="muted small">For all users in production, set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in Vercel Environment Variables and redeploy.</p></form></div>}
