function Landing(){return <div className="landing"><nav className="landing-nav"><Logo/><div className="nav-links"><a href="#features">Features</a><a href="#how">How it works</a><Link className="btn btn-ghost" to="/login">Log in</Link><Link className="btn btn-primary" to="/register">Get started <ArrowRight size={16}/></Link></div></nav><main className="hero"><div className="hero-copy"><div className="pill"><Sparkles size={14}/> A BETTER WAY TO ASK</div><h1>Questions, <span>with a point of view.</span></h1><p>Distinctive forms. Thoughtful interactions. Every response, in one place.</p><div className="hero-actions"><Link className="btn btn-primary btn-lg" to="/register">Create your first form <ArrowRight size={17}/></Link><Link className="btn btn-ghost btn-lg" to="/login">I have an account</Link></div><div className="trust-row"><span><Check size={15}/> Start free</span><span><Check size={15}/> Your data stays yours</span></div></div><div className="hero-visual"><div className="visual-glow"/><div className="mock-window"><div className="mock-top"><span/><span/><span/><small>Preview · New form</small></div><div className="mock-banner"><div className="mock-spark">✳</div><span>YOUR NEXT BIG IDEA STARTS HERE</span></div><div className="mock-form"><div className="mock-kicker">QUICK INTRODUCTION</div><h3>Tell us a little about you</h3><p>We'd love to get to know you better.</p><label>What's your name?</label><div className="mock-input">Enter your answer…</div><label>What are you interested in?</label><div className="mock-option"><i/> Design and creativity</div><div className="mock-option selected"><i/> Technology and building</div><div className="mock-option"><i/> Community and events</div><div className="mock-submit">Continue <ArrowRight size={15}/></div><div className="mock-progress"><i/></div></div></div><div className="float-card float-card-one"><span className="float-icon red"><Activity size={17}/></span><div><b>Smart logic</b><small>Personalized questions</small></div></div><div className="float-card float-card-two"><span className="float-icon purple"><BarChart3 size={17}/></span><div><b>Live insights</b><small>Responses at a glance</small></div></div></div></main><section id="features" className="feature-section"><div className="section-heading"><span className="eyebrow">BUILT FOR CREATORS</span><h2>Everything you need to ask better questions.</h2><p>From a quick signup to a fully branded, branching experience.</p></div><div className="feature-grid"><Feature icon={<Sparkles/>} title="Beautiful by default" desc="Create forms with custom colors, backgrounds, banners, typography and motion."/><Feature icon={<Activity/>} title="Logic that feels smart" desc="Show or hide questions and guide respondents down the right path."/><Feature icon={<BarChart3/>} title="Answers, organized" desc="Review submissions, explore trends and export your data."/><Feature icon={<Globe/>} title="Share anywhere" desc="Publish a public link or embed your form on your website."/></div></section><section id="how" className="bottom-cta"><div><span className="eyebrow">YOUR NEXT FORM STARTS HERE</span><h2>Make it yours. Share it. Learn from it.</h2><p>Start with a template or build something completely original.</p></div><Link className="btn btn-primary btn-lg" to="/register">Start building <ArrowRight size={17}/></Link></section><footer><Logo/><span>© {new Date().getFullYear()} DinuVoX Forms. Built for better questions.</span></footer></div>}
